P=Path(__file__).parent;m=json.loads((P/'texture-review-manifest.json').read_text());stats=json.loads((P/'runtime-measurements.json').read_text());primary=json.loads((P/'PRIMARY-SOURCE-MANIFEST.json').read_text());uri=lambda n:'data:image/png;base64,'+base64.b64encode((P/n).read_bytes()).decode()
html='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Northern Mockingbird — closed-eye candidate</title><style>body{font:16px system-ui;margin:24px;max-width:1150px;background:#ece7d8;color:#24372b}h1{font-size:24px}.row{display:flex;gap:24px;flex-wrap:wrap}.card{padding:14px;border:1px solid #b7b59f;border-radius:8px}canvas,img{image-rendering:pixelated}canvas{width:156.734693877551px;height:156.734693877551px}.dark{background:#17251f;color:#edf0dc}.light{background:#e5e0cd}button{padding:7px;margin:5px}pre{font-size:12px;white-space:pre-wrap}.crops img{max-width:260px}#status{font-variant-numeric:tabular-nums}</style></head><body><h1>Northern Mockingbird: one closed-eye candidate</h1><p>Existing awake source is reused unchanged. One new native closure, no new neutral/look or rigged motion. This is a candidate/study pending independent normal-size compatibility review. It is not an accepted blink slot or app binding.</p><p>Whole-canvas conversion only:1254²native→1024²registered→192²output. No translation, per-pose fit, source repaint or alpha cleanup. Existing density1.225output px/world unit is retained. Each canvas displays at156.735CSS px, making the bird80–81.633world px long.</p><button id="play">Play / restart</button><button id="pause">Pause</button><button id="open">Hold existing open</button><button id="closed">Hold new closed</button><label><input type="checkbox" id="overlay">Root/contact overlay</label><p id="status"></p><div class="row"><div class="card light"><p>Declared world size — light</p><canvas id="light" width="192" height="192"></canvas></div><div class="card dark"><p>Declared world size — dark</p><canvas id="dark" width="192" height="192"></canvas></div><div class="card light"><p>2x output inspection</p><canvas id="zoom" width="192" height="192" style="width:384px;height:384px"></canvas></div></div><p>30Hz open60ticks / closed3ticks / open27ticks.3second loop; closed100ms. Timings are product choices, not a measured natural blink rate. No body bob transform is applied. Body height72output px and lower foot boundary150px stay the same; full foot geometry is not locked.</p><p>Outside-eye redraw remains:alpha128silhouette IoU0.957709; visible outside-eye RGB difference15.609/255mean. Those measurements are diagnostics, not a pixel-equality gate. Grounded foot centroid changes0.547output px (~0.446world), mask Hausdorff1.414output px. Wing/body texture and tail-edge flicker need independent review at the declared display size.</p><img style="max-width:100%;height:auto" src="CONTACTS"><details><summary>Exact-timing standalone source APNG</summary><img width="192" height="192" style="width:156.734693877551px;height:156.734693877551px" src="__APNG_URI__"></details><details><summary>Exact source/intake/measurements</summary><pre>METADATA</pre></details><script>const manifest=MANIFEST,stats=STATS,urls=URLS;const ims={};let tick=0,playing=false,start=0;const canvases=['light','dark','zoom'].map(id=>document.getElementById(id));function state(){const phase=tick>=60&&tick<63?'closed':'open';return{tick,phase,outputFrameId:phase==='open'?OPENID:CLOSEDID,rootOutputXY:[114,150],density:1.225,appBound:false}}function draw(t){tick=((Math.floor(t)%90)+90)%90;const s=state();for(const c of canvases){const ctx=c.getContext('2d');ctx.imageSmoothingEnabled=false;ctx.fillStyle=c.id==='dark'?'#17251f':'#e5e0cd';ctx.fillRect(0,0,192,192);ctx.drawImage(ims[s.phase],0,0);if(document.getElementById('overlay').checked){ctx.fillStyle='#07b876';for(const a of manifest.frames[0].contacts)ctx.fillRect(a.x-1,a.y-1,2,2);ctx.strokeStyle='#d77d20';ctx.beginPath();ctx.moveTo(111,150);ctx.lineTo(117,150);ctx.moveTo(114,147);ctx.lineTo(114,153);ctx.stroke()}}document.getElementById('status').textContent=`Tick${tick}/89 • ${s.phase} • density1.225 • unchangedroot[114,150]`;return s}function raf(now){if(playing)draw((now-start)*30/1000);requestAnimationFrame(raf)}function play(){start=performance.now();playing=true;draw(0)}document.getElementById('play').onclick=play;document.getElementById('pause').onclick=()=>playing=false;document.getElementById('open').onclick=()=>{playing=false;draw(0)};document.getElementById('closed').onclick=()=>{playing=false;draw(60)};document.getElementById('overlay').onchange=()=>draw(tick);window.MOCKINGBIRD_REVIEW={ready:false,seek:t=>{playing=false;return draw(t)},getState:state,play,pause:()=>playing=false,manifest,stats};Promise.all(Object.entries(urls).map(([name,url])=>new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>{ims[name]=im;resolve()};im.onerror=reject;im.src=url}))).then(()=>{window.MOCKINGBIRD_REVIEW.ready=true;draw(0);requestAnimationFrame(raf)});</script></body></html>'''
html=html.replace('CONTACTS',uri('normal-light-dark-eye-feet.png')).replace('__APNG_URI__',uri('blink.apng')).replace('METADATA',json.dumps({'source':primary,'intake':m,'measurements':stats},indent=2)).replace('MANIFEST',json.dumps(m)).replace('STATS',json.dumps(stats)).replace('URLS',json.dumps({'open':uri('open192.png'),'closed':uri('closed192.png')})).replace('OPENID',json.dumps(primary['reusedFrames'][0]['outputFrameId'])).replace('CLOSEDID',json.dumps(primary['frames'][0]['outputFrameId']));(P/'review.html').write_text(html)
